function getFlag(countryName) {
  if (!countryName) return null;
  const c = allCountries.find(c => c.description.toLowerCase() === countryName.toLowerCase());
  return c?.flag;
}

function statChip(value, color, textColor = '#fff') {
  return (
    <Chip
      label={value}
      size="small"
      style={{ fontSize: '0.65rem', height: 20, fontWeight: 700, backgroundColor: color, color: textColor, minWidth: 28 }}
    />
  );
}

function CoachDialog({ coach, seasonYearById, onClose }) {
  const classes = useStyles();
  const [details, setDetails] = useState(null);
  const [loadingDetails, setLoadingDetails] = useState(true);

  useEffect(() => {
    if (!coach) return;
    setDetails(null);
    setLoadingDetails(true);
    fetch(`${API}/coachesDetails.php?id=${coach.id}`)
      .then(r => r.json())
      .then(list => {
        const seasons = list
          .map(s => ({
            year: seasonYearById[s.ID_S] || s.ID_S,
            id: s.ID_S,
            v: parseInt(s.v) || 0,
            d: parseInt(s.d) || 0,
            l: parseInt(s.l) || 0,
          }))
          .sort((a, b) => String(b.year).localeCompare(String(a.year)));

        const totals = seasons.reduce((acc, s) => ({ v: acc.v + s.v, d: acc.d + s.d, l: acc.l + s.l }), { v: 0, d: 0, l: 0 });
        setDetails({ seasons, ...totals });
        setLoadingDetails(false);
      })
      .catch(() => setLoadingDetails(false));
  }, [coach, seasonYearById]);

  if (!coach) return null;
  const tot = details ? details.v + details.d + details.l : 0;
  const winPct = tot > 0 ? Math.round((details.v / tot) * 100) : 0;

  return (
    <Dialog open onClose={onClose} maxWidth="xs" fullWidth>
      <DialogTitle style={{ paddingBottom: 8 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <Flag filename={getFlag(coach.country)} country={coach.country} />
          <Typography style={{ fontWeight: 700, fontSize: '1rem', flex: 1 }}>
            {coach.surname} {coach.name}
          </Typography>
          <IconButton size="small" onClick={onClose}><CloseIcon fontSize="small" /></IconButton>
        </div>
      </DialogTitle>
      <Divider />
      <DialogContent style={{ padding: '12px 16px' }}>
        {loadingDetails ? (
          <Box style={{ display: 'flex', justifyContent: 'center', padding: 24 }}>
            <CircularProgress size={28} />
          </Box>
        ) : (
          <>
            <Box style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap', marginBottom: 12 }}>
              <Chip
                label={`${details.seasons.length} stagion${details.seasons.length === 1 ? 'e' : 'i'}`}
                size="small"
                style={{ fontWeight: 700, backgroundColor: '#082D68', color: '#fff', fontSize: '0.68rem' }}
              />
              {statChip(details.v, '#4caf50')}
              {statChip(details.d, '#9e9e9e')}
              {statChip(details.l, '#CA2331')}
              <Typography style={{ fontSize: '0.78rem', fontWeight: 700 }}>{tot} partite</Typography>
              <Chip
                label={`${winPct}% vittorie`}
                size="small"
                style={{
                  fontSize: '0.65rem', height: 20, fontWeight: 700,
                  backgroundColor: winPct >= 50 ? 'rgba(76,175,80,0.15)' : 'rgba(202,35,49,0.10)',
                  color: winPct >= 50 ? '#2e7d32' : '#b71c1c',
                }}
              />
            </Box>

            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell className={classes.dialogSubCell} style={{ fontWeight: 700, color: '#082D68' }}>Stagione</TableCell>
                  <TableCell className={classes.dialogSubCell} align="center" style={{ fontWeight: 700, color: '#082D68' }}>V</TableCell>
                  <TableCell className={classes.dialogSubCell} align="center" style={{ fontWeight: 700, color: '#082D68' }}>P</TableCell>
                  <TableCell className={classes.dialogSubCell} align="center" style={{ fontWeight: 700, color: '#082D68' }}>S</TableCell>
                  <TableCell className={classes.dialogSubCell} align="center" style={{ fontWeight: 700, color: '#082D68' }}>Tot</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {details.seasons.map(s => (
                  <TableRow key={s.id}>
                    <TableCell className={classes.dialogSubCell}>{s.year}</TableCell>
                    <TableCell className={classes.dialogSubCell} align="center">{statChip(s.v, '#4caf50')}</TableCell>
                    <TableCell className={classes.dialogSubCell} align="center">{statChip(s.d, '#9e9e9e')}</TableCell>
                    <TableCell className={classes.dialogSubCell} align="center">{statChip(s.l, '#CA2331')}</TableCell>
                    <TableCell className={classes.dialogSubCell} align="center">
                      <Typography style={{ fontSize: '0.74rem', fontWeight: 600 }}>{s.v + s.d + s.l}</Typography>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </>
        )}
      </DialogContent>
    </Dialog>
  );
}

export default function CoachesPage() {
  const classes = useStyles();
  const [coaches, setCoaches] = useState([]);
  const [loading, setLoading] = useState(true);
  const [orderBy, setOrderBy] = useState('name');
  const [orderDir, setOrderDir] = useState('asc');
  const [query, setQuery] = useState('');
  const [countryFilter, setCountryFilter] = useState(null);
  const [page, setPage] = useState(0);
  const [selectedCoach, setSelectedCoach] = useState(null);
  const seasonYearByIdRef = useRef({});
  const rowsPerPage = 25;

  useEffect(() => {
    let isMounted = true;
    async function load() {
      try {
        const [coachesRes, seasonsRes] = await Promise.all([
          fetch(`${API}/allCoaches.php`),
          fetch(`${API}/seasons.php`),
        ]);
        const [list, seasons] = await Promise.all([coachesRes.json(), seasonsRes.json()]);
        seasons.forEach(s => { seasonYearByIdRef.current[s.id] = s.year; });
        if (isMounted) {
          setCoaches(list);
          setLoading(false);
        }
      } catch {
        if (isMounted) setLoading(false);
      }
    }
    load();
    return () => { isMounted = false; };
  }, []);

  const handleSort = (col) => {
    if (orderBy === col) {
      setOrderDir(d => d === 'asc' ? 'desc' : 'asc');
    } else {
      setOrderBy(col);
      setOrderDir('asc');
    }
    setPage(0);
  };

  const handleQuery = (q) => { setQuery(q); setPage(0); };
  const handleCountryFilter = (c) => { setCountryFilter(prev => prev === c ? null : c); setPage(0); };

  const countryOptions = Object.values(
    coaches.reduce((acc, c) => {
      if (!c.country) return acc;
      if (!acc[c.country]) acc[c.country] = { country: c.country, flag: getFlag(c.country), count: 0 };
      acc[c.country].count++;
      return acc;
    }, {})
  ).sort((a, b) => b.count - a.count);

  const sorted = [...coaches].sort((a, b) => {
    const mul = orderDir === 'asc' ? 1 : -1;
    return mul * (`${a.surname} ${a.name}`).localeCompare(`${b.surname} ${b.name}`);
  });

  let filtered = sorted;
  if (query) {
    const re = new RegExp(escareRegExp(query), 'i');
    filtered = filtered.filter(c => re.test(c.name) || re.test(c.surname));
  }
  if (countryFilter) {
    filtered = filtered.filter(c => c.country === countryFilter);
  }

  const paginated = filtered.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage);

  return (
    <div>
      <SEO
        title="Allenatori"
        description="Tutti gli allenatori della storia del Cagliari Calcio: stagioni, vittorie, pareggi, sconfitte e percentuale di successo."
        path="/cagliari-calcio/allenatori"
      />

      <Card className={classes.navCard}>
        <div className={classes.navHeader}>
          <Sidebar iconColor="#F0C040" />
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, flex: 1 }}>
            <img
              src="https://www.archiviorossoblu.it/images/sun-gold-sella-bg.png"
              alt="logo"
              title="ArchivioRossoBlu"
              style={{ width: 80, height: 80, flexShrink: 0 }}
            />
            <Typography component="a" href="/cagliari-calcio" className={classes.brand} style={{ flex: 'none' }}>
              <span className="brand-short" title="ArchivioRossoBlu">ARB</span>
              <span className="brand-full">ArchivioRossoBlu</span>
            </Typography>
          </div>
          <YouTubeLink />
          <ShareButtons />
          <Chip label="Allenatori" size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />
        </div>
        <Divider />
      </Card>

      <Box p={2}>
        <Breadcrumb items={[{ label: 'Home', href: '/cagliari-calcio' }, { label: 'Allenatori' }]} />
        <Grid container spacing={2}>
          <Grid item xs={12}>
            <Card className={classes.tableCard}>
              <CardHeader
                avatar={
                  <Chip label={loading ? '…' : filtered.length} size="small"
                    style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />
                }
                title="Allenatori della storia"
                subheader="Cagliari Calcio — clicca su una riga per i dettagli"
              />
              <Divider />

              <Box style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '8px 12px', flexWrap: 'wrap' }}>
                <div className={classes.searchBar}>
                  <SearchIcon style={{ color: 'rgba(8,45,104,0.4)', fontSize: '1.1rem' }} />
                  <InputBase
                    placeholder="Cerca…"
                    value={query}
                    onChange={e => handleQuery(e.target.value)}
                    inputProps={{ style: { fontSize: '0.82rem', width: 140 } }}
                  />
                </div>
                {countryOptions.map(({ country, flag, count }) => (
                  <Chip
                    key={country}
                    size="small"
                    onClick={() => handleCountryFilter(country)}
                    icon={
                      flag
                        ? <img src={getFlagUrl(flag)} alt={country} style={{ width: 16, height: 12, borderRadius: 2, marginLeft: 6 }} />
                        : undefined
                    }
                    label={`${country} (${count})`}
                    style={{
                      fontSize: '0.65rem',
                      height: 22,
                      fontWeight: 700,
                      cursor: 'pointer',
                      backgroundColor: countryFilter === country ? '#082D68' : 'rgba(8,45,104,0.08)',
                      color: countryFilter === country ? '#fff' : '#082D68',
                    }}
                  />
                ))}
              </Box>

              <CardContent style={{ padding: 0 }}>
                <TableContainer>
                  <Table stickyHeader size="small">
                    <TableHead>
                      <TableRow>
                        <TableCell className={classes.header}>
                          <TableSortLabel active={orderBy === 'name'} direction={orderDir} onClick={() => handleSort('name')}>
                            Allenatore
                          </TableSortLabel>
                        </TableCell>
                        <TableCell className={classes.header}>Nazionalità</TableCell>
                        <TableCell className={classes.header}>Nato il</TableCell>
                        <TableCell className={classes.header}>Luogo di nascita</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {loading ? (
                        Array.from({ length: 10 }).map((_, i) => (
                          <TableRow key={i}>
                            <TableCell colSpan={4}>
                              <Skeleton animation="wave" height={36} />
                            </TableCell>
                          </TableRow>
                        ))
                      ) : paginated.map((coach) => (
                        <TableRow key={coach.id} className={classes.row} onClick={() => setSelectedCoach(coach)}>
                          <TableCell className={classes.cell}>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                              <Flag filename={getFlag(coach.country)} country={coach.country} />
                              <Typography style={{ fontSize: '0.82rem', fontWeight: 600 }}>
                                {coach.surname} {coach.name}
                              </Typography>
                            </div>
                          </TableCell>
                          <TableCell className={classes.cell}>
                            <Typography style={{ fontSize: '0.78rem', color: 'rgba(0,0,0,0.55)' }}>
                              {coach.country}
                            </Typography>
                          </TableCell>
                          <TableCell className={classes.cell}>
                            <Typography style={{ fontSize: '0.78rem', color: 'rgba(0,0,0,0.55)' }}>
                              {coach.dateofbirth && coach.dateofbirth !== '0000-00-00'
                                ? new Date(coach.dateofbirth).toLocaleDateString('it-IT', { day: '2-digit', month: '2-digit', year: 'numeric' })
                                : '—'}
                            </Typography>
                          </TableCell>
                          <TableCell className={classes.cell}>
                            <Typography style={{ fontSize: '0.78rem', color: 'rgba(0,0,0,0.55)' }}>
                              {coach.placeofbirth || '—'}
                            </Typography>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                    <TableFooter>
                      <TableRow>
                        <TablePagination
                          colSpan={4}
                          count={filtered.length}
                          rowsPerPage={rowsPerPage}
                          rowsPerPageOptions={[rowsPerPage]}
                          page={page}
                          onPageChange={(_, newPage) => setPage(newPage)}
                          ActionsComponent={TablePaginationActions}
                          labelDisplayedRows={({ from, to, count }) => `${from}–${to} di ${count}`}
                        />
                      </TableRow>
                    </TableFooter>
                  </Table>
                </TableContainer>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      </Box>

      <CoachDialog
        coach={selectedCoach}
        seasonYearById={seasonYearByIdRef.current}
        onClose={() => setSelectedCoach(null)}
      />

      <Footer />
    </div>
  );
}
